import{_ as n,C as i,o,c as h,a3 as l,E as p,w as d,j as a,a as s}from"./chunks/framework.DoXyill7.js";const b=JSON.parse('{"title":"For agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/for-agents.md","filePath":"ai/for-agents.md"}'),r={name:"ai/for-agents.md"};function c(g,e,m,k,u,f){const t=i("ManualRelated");return o(),h("div",null,[e[1]||(e[1]=l(`<h1 id="for-agents" tabindex="-1">For agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to &quot;For agents&quot;">​</a></h1><p>What an agent reads to work with the S32, and how to point it at the right page.</p><h2 id="llms-txt-and-markdown-copies" tabindex="-1">llms.txt and Markdown copies <a class="header-anchor" href="#llms-txt-and-markdown-copies" aria-label="Permalink to &quot;llms.txt and Markdown copies&quot;">​</a></h2><p><a href="/versions/v1.1.3/llms.txt">llms.txt</a> is an index of the AI and s32 CLI pages. Every page it links, except the manual home, is a Markdown copy of a manual page: the same text without the site around it. Add <code>.md</code> to the address of a page under <code>/ai/</code> or <code>/developers/</code> to get its copy, for example <code>/ai/setup.md</code>.</p><h2 id="page-buttons" tabindex="-1">Page buttons <a class="header-anchor" href="#page-buttons" aria-label="Permalink to &quot;Page buttons&quot;">​</a></h2><p>Every page under Use the S32 with AI and under s32 CLI has three buttons at the top:</p><ul><li><strong>Copy page</strong> copies the Markdown of the page to your clipboard.</li><li><strong>Open in ChatGPT</strong> opens ChatGPT with a prompt that points at the Markdown copy of the page.</li><li><strong>Open in Claude</strong> opens Claude with the same prompt.</li></ul><p>The prompt names the page and nothing else: no text from the page, and nothing about you.</p><h2 id="discover-the-commands" tabindex="-1">Discover the commands <a class="header-anchor" href="#discover-the-commands" aria-label="Permalink to &quot;Discover the commands&quot;">​</a></h2><p>An agent finds commands the way you do. <code>s32 --help</code> lists them, <code>s32 &lt;command&gt; --help</code> shows the keys of one, <code>s32 commands --json</code> lists everything for a program, and <code>s32 schema --emit-schema-json</code> lists each device&#39;s parameters with their ids and ranges.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-schema-json</span></span></code></pre></div><h2 id="batches" tabindex="-1">Batches <a class="header-anchor" href="#batches" aria-label="Permalink to &quot;Batches&quot;">​</a></h2><p>A script runs one command per line, so an agent can do a whole setup in one go. Save the lines in a file, then run it with <code>--script</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>device add 1 arp</span></span>
<span class="line"><span>device param set 1 2 rate=6</span></span>
<span class="line"><span>device list 1</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.script</span></span></code></pre></div><p>A script stops at the first line that fails and exits with that line&#39;s code. Commands that ask first need <code>--yes</code> on their line. For a session you steer by hand, use <code>repl</code>: see <a href="./../developers/simulator">Simulator and scripts</a>.</p>`,16)),p(t,null,{default:d(()=>[...e[0]||(e[0]=[a("ul",null,[a("li",null,[a("a",{href:"./"},"Overview"),s(" — What an agent can do with your S32, in three steps")]),a("li",null,[a("a",{href:"./setup"},"Set up your agent"),s(" — Paste one block; the agent installs, checks and saves the rules")]),a("li",null,[a("a",{href:"./prompts"},"Prompts and examples"),s(" — Quick starters and prompts for racks, modulation and knob mappings, with checked commands")]),a("li",null,[a("a",{href:"./safe-changes"},"Change safely"),s(" — Read, preview, ask, change, check")])],-1)])]),_:1})])}const C=n(r,[["render",c]]);export{b as __pageData,C as default};
